    String[] array = new String[size];
    Iterator<?> iterator = collection.iterator();
    int i = 0;

    while (iterator.hasNext()) {
        Object obj = iterator.next();
        if (obj != null) {
            array[i++] = (String) obj;
        } else {
            throw new IllegalArgumentException("Collection contains null element at position " + i);
        }
    }

    if (i != size) {
        throw new IllegalArgumentException("Collection contained a mix of null and non-null objects");
    }

    return array;
}

