    while (end < headerPart.length() && headerPart.charAt(end) != '\r') {
        end++;
    }
    if (end >= headerPart.length() || headerPart.charAt(end) != '\n') {
        throw new RuntimeException("Expected line terminator '\\n', but found: " + headerPart.charAt(end));
    }
    return Integer.valueOf(headerPart.substring(end + 1));
}

