public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    int numVertices = 0;
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        numVertices += entry.getValue().getNumVertices();
    }

    target.addVerticesWithIDs(numVertices);
    Map<Integer, HashSet<Integer>> adjacencyList = new HashMap<>();
    for (V vertex : target.getVertices()) {
        adjacencyList.put(vertex.getId(), new HashSet<>());
    }

    List<E> edges = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        for (int neighborId : entry.getValue().getNeighbors().keySet()) {
            E edge = new GraphEdge(target.getVertex(neighborId), entry.getValue());
            target.addEdge(edge);
            adjacencyList.get(entry.getValue().getId()).add(neighborId);
            adjacencyList.get(neighborId).add(entry.getValue().getId());
            edges.add(edge);
        }
    }

    target.addEdgesWithIDs(edges);
}

