private void generateCompleteBipartiteGraph(Graph<V,E> target, Map<String,V> resultMap) {
    List<String> vertexList = new ArrayList<>(resultMap.keySet());
    int numVertices1 = vertexList.size() / 2;
    int numVertices2 = vertexList.size() / 2;

    for (int i = 0; i < numVertices1; i++) {
        for (int j = 0; j < numVertices2; j++) {
            target.addEdge(resultMap.get(vertexList.get(i)), resultMap.get(vertexList.get(j + numVertices1)));
        }
    }
}

