    if (edge == null || edge.getTail() == null || edge.getHead() == null || edge.getTail() == edge.getHead()) {
        return;
    }

    // Remove the edge from the tail's list
    TreeEdge next = edge.getTail().getNext();
    if (next == null) {
        edge.getTail().setNext(null);
    } else {
        next.setPrev(null);
    }

    // Remove the edge from the head's list
    TreeEdge prev = edge.getHead().getPrev();
    if (prev == null) {
        edge.getHead().setPrev(null);
    } else {
        prev.setNext(null);
    }

    // Clear the pointers
    edge.setTail(null);
    edge.setHead(null);
}

