        switch (r.getTransport()) {
            case PIPE:
                Logger logger = r.getLogger();
                logger.info("Pipe transport detected. Suspending AtmosphereResource.");
                r.suspend(null);
                break;
            case WebSocket:
                Logger logger = r.getLogger();
                logger.info("WebSocket transport detected. Suspending AtmosphereResource.");
                r.suspend(null);
                break;
            case LongPolling:
                Logger logger = r.getLogger();
                logger.info("LongPolling transport detected. Suspending AtmosphereResource.");
                r.suspend(null);
                break;
            case JSONP:
                Logger logger = r.getLogger();
                logger.info("JSONP transport detected. Suspending AtmosphereResource.");
                r.suspend(null);
                break;
            case Streaming:
                Logger logger = r.getLogger();
                logger.info("Streaming transport detected. Suspending AtmosphereResource.");
                r.suspend(null);
                break;
        }
        return Action.CONTINUE;
    } else {
        return Action.CONTINUE;
    }
}

