    // Check if the map contains the key
    if (!map.containsKey(key)) {
        // If the map does not contain the key, initialize it with the given value
        map.put(key, new AtomicLong(value));
    } else {
        // If the map contains the key, add the given value to the existing value
        map.compute(key, (k, v) -> new AtomicLong(v.get() + value));
    }
